/// C-FFI dispatch descriptor for SunSpec model 4. A C `SunspecModelBinding` points
/// at this static, so the service functions dispatch with no model-id lookup.
#[unsafe(no_mangle)]
pub static SUNSPEC_MODEL_4: StaticModelSpec = StaticModelSpec {
    id: 4,
    length: model_4_c_length,
    writable: false,
    visit_read: model_4_c_visit_read,
    visit_write: model_4_c_visit_write,
};

fn model_4_c_length(_repeat_count_0: u16, _repeat_count_1: u16) -> u16 {
    (Model4).model_length()
}

/// # Safety
/// For `kind` 1 or 2, `adapter` must point to a live `Model4{Stateful,Callback}Adapter`,
/// valid for the duration of the call.
unsafe fn model_4_c_visit_read(
    kind: u8,
    adapter: *const c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &mut WritableRegisterBuffer<'_>,
) {
    let model = Model4;
    let adapter: Option<&dyn ReadAdapter> = match kind {
        1 => Some(unsafe { &*(adapter as *const Model4StatefulAdapter) } as &dyn ReadAdapter),
        2 => Some(unsafe { &*(adapter as *const Model4CallbackAdapter) } as &dyn ReadAdapter),
        _ => None,
    };
    cursor.visit_source_block(model.model_length(), |offset, from, len| {
        let mut block = buffer.slice(from, len);
        match adapter {
            Some(adapter) => model.traverse_points_read(adapter, &mut block, offset),
            None => {
                block.fill(&[0xff, 0xff]);
                Ok(())
            }
        }
    });
}

/// # Safety
/// As for [`model_4_c_visit_read`], and `adapter` must be uniquely borrowable for the call.
unsafe fn model_4_c_visit_write(
    kind: u8,
    adapter: *mut c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &ReadableRegisterBuffer<'_>,
) {
    let _ = (kind, adapter, buffer);
    let model = Model4;
    cursor.visit_source_block(model.model_length(), |_, _, _| {
        Err(ModbusException::IllegalDataAddress)
    });
}
